INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('junshi', '均施', '钙镁肥', '{"id":"junshi","name":"均施","category":"钙镁肥","intro":"中量元素水溶肥料（颗粒），钙镁同补，缓解盐碱、促进光合:\n\n本产品选取优质矿质资源，经氨基酸、海藻酸进行螯合，富含镁、钙、硼、锌、铁等中微量元素以及海藻、γ- 氨基丁酸和氨基酸营养，为土壤及农作物补充丰富的无机和有机营养，有助于土壤改善和提升作物长势，适合于滴灌、撒施、底肥以及叶面喷施，产品不含重金属物质，属于安全绿色种植的优秀产品。","description":"Ca 2%、Mg 8%，含B 0.15%、Zn 0.15%、Fe 0.7%","advantages":"钙镁同补；不含氮，果实上色期不返青；缓解盐碱:\n\n1.真螯合抗拮抗，可与磷钾肥混用不沉淀，解决普通钙肥混配痛点\n2.零氮零氯零重金属，转色期使用不返青不刺激旺长\n3.用法灵活，冲施滴灌、撒施埋肥、叶面喷施均可\n4.有机无机双效，海藻酸促根增强整体抗逆性\n5.缓解盐碱障碍，置换钠离子，适用盐碱地改良","ingredients":"Ca 2%、Mg 8%、B 0.15%、Zn 0.15%、Fe 0.7%","functions":"钙镁同补、防裂果、防缺镁黄叶:\n\n1.补充镁元素，增加农作物的光合作用，有助于促进蛋白质、淀粉和叶绿素的形成，避免因缺镁元素出现的叶片发黄和黄化现象；\n2.补充钙元素，钙是维持农作物细胞形状和稳定性的重要元素，有助于减少农作物生长过程中因缺钙出现的各种生理性障碍；\n3.补充铁锌硼等微量元素，促进营养相互协同和运转效率，同时有助于根系发育、避免因缺乏微量元素带来的不良生长；\n4.本产品不含氮元素，氯钠和重金属指标均符合最高限量要求，适合于农作物各个生长阶段，果实上色成熟阶段使用本产品不会出现返青现象；\n5.产品和土壤胶体吸附的钠离子发生置换，与盐碱地有酸碱中和作用，有助于缓解土壤盐碱障碍；","applicable_crops":"果树、蔬菜、经济作物均可","usage":"冲施滴灌：重缺镁钙3-5kg/亩、日常1-2kg/亩；叶面喷施：1000-1500倍。新产品主推，均可使用","price_range":"1.5kg/袋，20kg/袋","mix_profile":{"ph":"3.92","has_copper":false,"copper_level":"none","has_calcium":true,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":false,"has_phosphorus":false,"has_silicon":false,"is_alkaline":false,"is_acidic":true},"manufacturer":"韩国丰产生物株式会社","seller":"深圳喜沃生态科技有限公司","origin":"韩国","registrations":{"execution_standard":"NY2266-2012","record_number":"ZLSRJK2020-00246"},"specifications":[{"name":"20Kg","capacity":"20Kg","form":"颗粒"}],"images":["images/products/junshi.png"]}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_product_specs (id, product_id, name, capacity, form, payload_json, sort_order) VALUES ('legacy-spec-b66b96b8cc1e07be4ab6dc0204f6', 'junshi', '20Kg', '20Kg', '颗粒', '{"name":"20Kg","capacity":"20Kg","form":"颗粒"}', '0');
INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('zhuoyan', '卓艳', '大量元素水溶肥料', '{"id":"zhuoyan","name":"卓艳","category":"大量元素水溶肥料","intro":"大量元素水溶肥料（水剂），着色期专研配方，调节糖氮、果甜色正：\n\n卓艳专为果实膨大期后的生理需求研发，重点促进糖分快速积累、均匀转色及品质提升。产品采用中后期螯合工艺，将高浓度钾与葡萄糖酸、氨基酸等有机营养复合，能快速促进细胞膨大，提高果皮韧性和果实硬度，增强叶片光合效率，促进果实上糖、转色和成熟。同时，卓艳能强化作物树势，调节营养平衡，减少畸形果和裂果的发生，适用于瓜果及蔬菜类高频率使用。","description":"转色上糖专用，N 40g/L、P 100g/L、K 350g/L，含黄腐酸30g/L、腐殖酸30g/L、有机质280g/L、游离氨基酸30g/L、Zn 1g/L、B 1g/L","advantages":"着色期专研配方；乳酸螯合工艺，温和补钾不伤根：\n\n采用乳酸螯合工艺，有效避免钾离子被土壤固定及与钙、镁、硼等元素的拮抗，大幅提升钾素当季利用率。  产品呈弱酸性且盐分指数低，高频次冲施不会损伤毛细根，规避了传统无机钾肥导致的土壤酸化与次生盐渍化。  构建有机与无机协同体系，将高活性钾配合黄腐酸、氨基酸等高浓度有机碳源科学配比。","ingredients":"N 40g/L、P 100g/L、K 350g/L、黄腐酸30g/L、有机质280g/L、腐殖酸30g/L、游离氨基酸30g/L、Zn 1g/L、B 1g/L","functions":"转色上糖、膨果着色、提高果实品质：\n\n1.补充高活性钾，调节果实糖酸比：有利于改善因偏施氮肥或阴雨寡照造成的口感寡淡和上色慢问题，促进果实增糖转色。\n2.小分子形态，吸收效率高：有利于规避传统钾肥导致的土壤酸化、盐渍化与板结，保护作物根系不受损伤。\n3.富含有机营养，促进土壤微生物活性：提升土壤透气性与根系生长活力，减轻果实中后期的根系早衰问题。\n4.调节作物气孔开闭与细胞渗透压，降低蒸腾失水：帮助植株在干旱、低温或盐碱胁迫下维持正常生理代谢，减轻逆境伤害。","applicable_crops":"果树、瓜菜等需转色作物","usage":"瓜菜4-5kg/亩，果树8-10kg/亩；喷施500-800倍。液体，冲施喷施均可。新产品主推","price_range":"5kg/桶，20kg/桶","mix_profile":{"ph":"6","has_copper":false,"copper_level":"none","has_calcium":false,"has_humic_acid":true,"has_amino_acid":true,"has_microbe":false,"has_phosphorus":true,"has_silicon":false,"is_alkaline":false,"is_acidic":true},"manufacturer":"皓泽农业（广州）有限公司","seller":"深圳惠民皓天生态科技有限公司","origin":"中国","registrations":{"execution_standard":"NY/T 1107-2020","record_number":"DLSRGD2022-00146"},"specifications":[{"name":"5Kg","capacity":"5Kg","form":"水剂"}],"images":["images/products/zhuoyan1.png"]}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_product_specs (id, product_id, name, capacity, form, payload_json, sort_order) VALUES ('legacy-spec-76005ebfaed30aeef83abb848f50', 'zhuoyan', '5Kg', '5Kg', '水剂', '{"name":"5Kg","capacity":"5Kg","form":"水剂"}', '0');
INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('aojing', '傲净', '微生物菌剂', '{"id":"aojing","name":"傲净","category":"微生物菌剂","intro":"微生物菌剂（液体），复合型菌剂，土壤微生态提升：\n\n本品为复合型微生物菌剂，采用枯草芽孢杆菌、贝莱斯芽孢杆菌、胶冻样芽孢杆菌等多种菌群科学复配而成，属于土壤微生态提升型产品。适用于土壤调理与生长辅助，涵盖土壤改良、促生、营养活化、降解有毒有害物质、改善农产品品质等多种功能。通过微生物协同作用，改善土壤环境，为作物健康生长提供有利环境。","description":"液体剂型，3大靶向功能菌（枯草+贝莱斯+胶冻样），549.7亿CFU/g","advantages":"3大靶向功能菌；有效活菌数≥100亿/mL：\n\n1.采用高浓度液体发酵工艺，有效活菌数高达500亿/g，以高抗逆芽孢形态确保在常温液体中的稳定储存与极高定殖率。 \n2. 构建靶向复合菌群生态，科学配比枯草芽孢杆菌、胶冻样芽孢杆菌与贝莱斯芽孢杆菌，实现菌群协同增效且不内耗。  \n3.液体剂型无残渣，兼容冲施、滴灌与叶面喷雾等多种施用途径，操作便捷且不堵塞管网。","ingredients":"3大靶向功能菌：枯草芽孢杆菌+贝莱斯芽孢杆菌+胶冻样芽孢杆菌，有效活菌数549.7亿CFU/g","functions":"靶向防病、调土生根、解磷解钾、抑制土传病原菌：\n\n1.依托菌株特性，缓解土壤板结问题：增加土壤团粒结构，提升土壤透气性与保水保肥能力，改善土壤微生态环境。\n2.帮助溶解土壤中固定的磷、钾等养分：转化为作物易吸收的形态，提高土壤养分利用率，为作物生长提供营养支持。\n3.有益于作物根系发育：提升作物根系吸收能力，助力壮苗、促生长，改善作物长势，为稳产提质奠定基础。\n4.通过调节土壤微生态与作物生长状态：增强作物对干旱、盐碱等不良环境的适应能力，减少不良环境对作物的影响。\n5.菌株代谢产生的活性物质可调节土壤微生态平衡：增强作物自身生长韧性，助力作物苗期健壮生长，从而减少死苗情况。","applicable_crops":"果树、蔬菜、瓜类、经济作物均可","usage":"冲施/滴灌 + 叶面喷施","mix_profile":{"ph":"7","has_copper":false,"copper_level":"none","has_calcium":false,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":true,"has_phosphorus":false,"has_silicon":false,"is_alkaline":false,"is_acidic":false},"manufacturer":"广州益国农业科技有限公司","seller":"深圳惠民皓天生态科技有限公司","origin":"中国","registrations":{"fertilizer_registration":"微生物肥(2024)准字(14389)号","execution_standard":"GB20287-2006","effective_bacteria":"枯草芽孢杆菌"},"specifications":[{"name":"1000ml","capacity":"1000ml","form":"液体"}],"images":["images/products/aojing1.png"]}', '2026-08-22T01:14:46.869Z');
