INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('chutoumao_yudanbai', '锄头猫·有机水溶肥', '有机水溶肥', '{"id":"chutoumao_yudanbai","name":"锄头猫·有机水溶肥","category":"有机水溶肥","intro":"有机水溶肥料（水剂），含氨基酸、黄腐酸、蛋白质及微生物菌剂，生根养根","description":"鱼蛋白有机水溶肥，氨基酸≥100g/L、蛋白质200g/L，含黄腐酸100g/L、腐殖酸30g/L、有机质180g/L、NPK 60g/L、Ca+Mg 5g、B+Zn+Fe 20g/L，含微生物菌剂0.5亿/mL","advantages":"氨基酸+黄腐酸+蛋白质+微生物四效合一；生根养根","ingredients":"NPK 60g/L、Ca+Mg 5g、B+Zn+Fe 20g/L、有机质180g/L、腐殖酸30g/L、黄腐酸100g/L、氨基酸≥100g/L、蛋白质200g/L、微生物菌剂0.5亿/mL","functions":"生根养根、改良根际环境、促进根系发育","applicable_crops":"果树、蔬菜、瓜类、大田作物均可","usage":"幼苗期2.5L灌根1-2亩，开花结果期灌根1亩，或250-300倍。液体根际肥","price_range":"44元/桶","mix_profile":{"ph":"3.5","has_copper":false,"copper_level":"none","has_calcium":true,"has_humic_acid":true,"has_amino_acid":true,"has_microbe":true,"has_phosphorus":true,"has_silicon":false,"is_alkaline":false,"is_acidic":true},"manufacturer":"韩国阿米诺实验室株式会社","seller":"锄头邦网络科技（深圳）有限公司","origin":"韩国","registrations":{"fertilizer_registration":"农肥(2025)准字20124号","execution_standard":"NY 1429-2010"},"specifications":[{"name":"2.5L","capacity":"2.5L","form":"水剂"}],"images":["images/products/chutoumaoyoujifei1.png"]}', '2026-08-22T01:14:46.869Z');
