INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('chutoumao_duotai', '锄头猫·多肽氨基酸', '含氨基酸水溶肥料', '{"id":"chutoumao_duotai","name":"锄头猫·多肽氨基酸","category":"含氨基酸水溶肥料","intro":"含氨基酸水溶肥料（水剂），韩国进口游离氨基酸/多肽，抗逆解药害：\n\n本氨基酸系以动物血液为原料，经低温酵素酶解萃取，游离氨基酸种类达 17 种以上，富含有机质、多肽和小肽、左旋氨基酸、各种微量元素等。能帮助农作物抵御高低温胁迫，有利于作物快速生长，更好地开花挂果，提升果实糖分和品质，适合于农作物各阶段使用。","description":"韩国进口游离氨基酸/多肽，氨基酸≥100g/L，含有机氮≥25g、B≥7g/L、Fe≥11g/L、Zn≥3.5g/L、有机质≥240g","advantages":"韩国进口游离氨基酸；抗逆解药害：\n\n1.甄选日本核心菌种，采用枯草芽孢杆菌、胶冻样芽孢杆菌、贝莱斯芽孢杆菌为主要菌群科学复配，功能明确互补；\n2.有效活菌数基础极高，远超行业常规标准；\n3.先进的芽孢液体制剂技术，极其耐储存、不胀气，能够抵抗环境波动，在土壤中定殖能力极强。","ingredients":"有机氮≥25g、B≥7g/L、Fe≥11g/L、Zn≥3.5g/L、有机质≥240g、氨基酸≥100g/L","functions":"抗逆（抗旱抗寒）、解药害、促进生长：\n\n1.补充氨基酸营养：有助于减少农作物在高温或低温逆境情况下的营养损失。\n2.提升开花、挂果与果实品质：氨基酸可帮助农作物提升开花和挂果能力，有助于果实发育和甜度提高。\n3.缓解药害与逆境损伤：当连续下雨或干旱导致作物叶片出现异常时，使用氨基酸能帮助作物快速恢复生长状态。\n4.促进营养吸收与代谢：游离氨基酸无需被农作物复杂转化，属于作物可直接高效利用的营养物质，适合在农作物各阶段使用。","applicable_crops":"果树、蔬菜、瓜类、经济作物均可","usage":"逆境500倍，正常1000倍。液体叶面肥","price_range":"58.6元/瓶","mix_profile":{"ph":"6","has_copper":false,"copper_level":"none","has_calcium":false,"has_humic_acid":false,"has_amino_acid":true,"has_microbe":false,"has_phosphorus":false,"has_silicon":false,"is_alkaline":false,"is_acidic":true},"manufacturer":"韩国阿米诺实验室株式会社","seller":"锄头邦网络科技（深圳）有限公司","origin":"韩国","registrations":{"customs_declaration":"520220251025072210","import_contract":"25XW-AL002","fertilizer_registration":"农肥(2025)准字20124号","execution_standard":"NY 1429-2010"},"specifications":[{"name":"1000ml","capacity":"1000ml","form":"水剂"}],"images":["images/products/chutoumaoanjisuan (1).png","images/products/chutoumaoanjisuan (2).png","images/products/chutoumaoanjisuan (3).png"]}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_product_specs (id, product_id, name, capacity, form, payload_json, sort_order) VALUES ('legacy-spec-8b9b736e758603c5a6590b99218b', 'chutoumao_duotai', '1000ml', '1000ml', '水剂', '{"name":"1000ml","capacity":"1000ml","form":"水剂"}', '0');
INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('chutoumao_huaguo', '锄头猫·花果多', '微量元素水溶肥料', '{"id":"chutoumao_huaguo","name":"锄头猫·花果多","category":"微量元素水溶肥料","intro":"微量元素水溶肥料（水剂），硼钼同补，促花保果\n\n本品是针对作物促花稳果阶段生理需求研发的专用微量元素水溶肥。通过富含硼、钼与海藻的科学复配，强化养分离子的活性与移动性，帮助提升营养元素在作物体内的吸收与转运效率。既能帮助打破作物休眠，增强低温等逆境下的抗逆性，也能促进花芽分化，提升开花整齐度，同时辅助坐果稳果，减少花果脱落，还能帮助改善果实发育状态，降低畸形果、裂果等问题。","description":"硼120g/L+钼5g/L，含海藻精1g","advantages":"硼120g/L+钼5g/L高含量；含海藻提取物","ingredients":"B 120g/L、Mo 5g/L、海藻精1g","functions":"促花保果、提高坐果率、促进花粉管伸长\n\n含海藻提取物，有助于增强农作物在低温、干旱等逆境胁迫条件下的生长适应能力。\n含钼元素，参与作物体内氮素代谢过程，促进氮素高效转化与利用，有助于作物生殖发育，减少因氮素过量引起的开花坐果障碍。\n含硼元素，有助于促进花器官发育与授粉受精，提高坐果率，减少落花落果、花而不实等现象。\n有助于改善果实发育质量，使果皮更加光滑细腻，减少果皮粗糙、凹凸不平等生理性品质问题。\n有助于维持细胞壁结构稳定，减少果实开裂、裂果及畸形等生理性障碍发生。","applicable_crops":"果树、蔬菜、油菜、豆科作物等需硼钼作物","usage":"促花调花期使用1-2次，幼果期使用1次。叶面喷雾1000倍。液体叶面肥","price_range":"44.1元/瓶","mix_profile":{"ph":"8.82","has_copper":false,"copper_level":"none","has_calcium":false,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":false,"has_phosphorus":false,"has_silicon":false,"is_alkaline":false,"is_acidic":false},"manufacturer":"皓泽农业（广州）有限公司","seller":"锄头邦网络科技（深圳）有限公司","origin":"中国","registrations":{"execution_standard":"NY 1428-2010","record_number":"WLSRGD2025-01095"},"specifications":[{"name":"1000ml","capacity":"1000ml","form":"水剂"}],"images":["images/products/huaguoduo (1).png","images/products/huaguoduo (2).png"]}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_product_specs (id, product_id, name, capacity, form, payload_json, sort_order) VALUES ('legacy-spec-59f408bf60fe1c387a45b2278560', 'chutoumao_huaguo', '1000ml', '1000ml', '水剂', '{"name":"1000ml","capacity":"1000ml","form":"水剂"}', '0');
INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('chutoumao_gaogai', '锄头猫·高钙', '中量元素钙肥', '{"id":"chutoumao_gaogai","name":"锄头猫·高钙","category":"中量元素钙肥","intro":"中量元素水溶肥料（粉剂），高钙配方，防裂果、防脐腐病\n\n本品是通过植物提取进行螯合的新一代钙肥。其核心技术在于解决了钙元素在植物体内移动缓慢的问题，使钙在植物体内更快速地穿透和传导，提高了钙对农作物的吸收效率，从而帮助农作物减少因缺钙引起的各种生理性问题。","description":"Ca 20%，含B 0.05%、Cu 0.01%、Zn 0.02%","advantages":"钙≥20%高含量；粉剂易溶，冲施叶喷均可\n\n1. 采用新一代植物提取物与柠檬酸螯合技术，钙肥吸收与移动效率远超常规钙肥；\n2. 科学的复配微量元素，利用硼作为载体加速钙向果实末端的传导；\n3. 纯无氮配方，在果实转色及需钙高峰期连续使用，不会导致返青或成熟延迟；\n4. 产品混用性好，可与磷钾混用。","ingredients":"Ca 20%、B 0.05%、Cu 0.01%、Zn 0.02%","functions":"补钙、防裂果、防脐腐病、增强果实硬度\n\n补钙效率高，吸收更稳定，可应用于对钙需求量大或易缺钙的作物和关键生育期，不会引起果实返青和营养过剩问题。\n钙肥原料不含氮素营养，安全性高，在推荐使用倍数范围内混配性好，可与多种营养元素配合使用。\n钙能促进细胞壁形成，增强果实硬度和韧性，减少裂果、苦痘病、脐腐病等缺钙引起的生理问题。\n钙元素有助于提升果实品质和耐储运性，减少采后运输和储存过程中的损伤。\n可增强作物对干旱、高温等逆境的适应能力，减少因缺钙导致的生长异常和品质下降。","applicable_crops":"苹果、葡萄、番茄、辣椒、白菜等需钙作物","usage":"冲施/滴灌1kg/亩；叶面喷雾1000-1500倍，10-20g一壶水。粉剂叶面肥","price_range":"32.2元/瓶/1kg","mix_profile":{"ph":"4","has_copper":true,"copper_level":"trace","has_calcium":true,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":false,"has_phosphorus":false,"has_silicon":false,"is_alkaline":true,"is_acidic":false},"manufacturer":"皓泽农业（广州）有限公司","seller":"锄头邦网络科技（深圳）有限公司","origin":"中国","registrations":{"execution_standard":"NY 2266-2012","record_number":"ZLSRGD2022-00336"},"specifications":[{"name":"1000g","capacity":"1000g","form":"粉剂"},{"name":"10kg","capacity":"10kg","form":"粉剂"}],"images":["images/products/chutoumaogaogai (1).png","images/products/chutoumaogaogai (2).png","images/products/chutoumaogaogai (3).png","images/products/chutoumaogaogai (4).png"]}', '2026-08-22T01:14:46.869Z');
