INSERT OR REPLACE INTO legacy_product_specs (id, product_id, name, capacity, form, payload_json, sort_order) VALUES ('legacy-spec-7ae92ad2c19e506d2e8a0bb40a26', 'chutoumao_gaogai', '10kg', '10kg', '粉剂', '{"name":"10kg","capacity":"10kg","form":"粉剂"}', '1');
INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('chutoumao_junji', '锄头猫·微生物菌剂', '微生物菌剂', '{"id":"chutoumao_junji","name":"锄头猫·微生物菌剂","category":"微生物菌剂","intro":"复合型微生物菌剂（液体），多菌种科学复配，调土防病：\n\n本品为复合型微生物菌剂，采用枯草芽孢杆菌、贝莱斯芽孢杆菌、胶冻样芽孢杆菌等多种科学复配而成，属于土壤微生态提升型产品。适用于多种作物的土壤调理与生长辅助，涵盖土壤改良、促生、抑菌、营养活化等多种功能。通过微生物协同作用改善土壤环境，为作物健康生长提供有利环境。","description":"枯草芽孢杆菌133亿、胶冻样芽孢杆菌333亿、贝莱斯杆菌83亿，总有效活菌数≥500亿/g，含乳酸菌、酵母菌、纳豆菌等","advantages":"1. 甄选日本核心菌种，采用枯草芽孢杆菌、胶冻样芽孢杆菌、贝莱斯芽孢杆菌为主要菌群科学复配，功能明确互补；\n2. 有效活菌数基础极高，远超行业常规标准；\n3. 先进的芽孢液体制剂技术，极其耐储存、不胀气，能够抵抗环境波动，在土壤中定殖能力极强。","ingredients":"枯草芽孢杆菌133亿/g、胶冻样芽孢杆菌333亿/g、贝莱斯杆菌83亿/g，总≥500亿/g。另含乳酸菌、酵母菌、纳豆菌等","functions":"调土防病、解磷解钾、固氮、抑制土传病原菌、促根：\n\n1.依托菌株特性，缓解土壤板结问题，增加土壤团粒结构，提升土壤透气性与保水保肥能力，改善土壤微生态环境。\n2.帮助溶解土壤中固定的磷、钾等养分，转化为作物易吸收的形态，提高土壤养分利用率，为作物生长提供营养支持。\n3.有益于作物根系发育，提升作物根系吸收能力，助力壮苗、促生长，改善作物长势，为稳产提质奠定基础。\n4.通过调节土壤微生态与作物生长状态，增强作物对干旱、盐碱等不良环境的适应能力，减少不良环境对作物的影响。\n5.菌株代谢产生的相关物质，可辅助抑制土壤中部分有害病原菌繁殖，减少土传病害发生风险，降低死苗死棵概率。","applicable_crops":"果树、蔬菜、大田作物均可","usage":"每亩1000ml，500-600倍稀释；叶面喷雾600-800倍，一喷雾器25-30ml，间隔15天。液体根际或叶面","price_range":"44.1元/瓶","mix_profile":{"ph":"7.2","has_copper":false,"copper_level":"none","has_calcium":false,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":true,"has_phosphorus":false,"has_silicon":false,"is_alkaline":false,"is_acidic":false},"manufacturer":"广州益国农业科技有限公司","seller":"锄头邦网络科技（深圳）有限公司","origin":"中国","registrations":{"fertilizer_registration":"微生物肥(2024)准字(14389)号","execution_standard":"GB20287-2006"},"specifications":[{"name":"1000ml","capacity":"1000ml","form":"液体"}],"images":["images/products/chutoumao1weishenwujunji.png","images/products/chutoumao2weishenwujunji.png"]}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_product_specs (id, product_id, name, capacity, form, payload_json, sort_order) VALUES ('legacy-spec-53b13497d1eb967e38665fbe2982', 'chutoumao_junji', '1000ml', '1000ml', '液体', '{"name":"1000ml","capacity":"1000ml","form":"液体"}', '0');
INSERT OR REPLACE INTO legacy_products (id, name, category, payload_json, updated_at) VALUES ('fenghui', '沣惠', '中量元素钙肥', '{"id":"fenghui","name":"沣惠","category":"中量元素钙肥","intro":"中量元素水溶肥料（粉剂），植物提取物螯合新一代钙肥，补钙防裂：\n\n沣惠是通过植物提取物进行螯合的新一代肥料，其核心技术在于解决了钙元素在植物体内移动慢的问题，使钙在植物体内更快地被转运和吸收，提高钙对农作物的吸收效率，从而帮助农作物减少因缺钙引起的各种生理性问题，提升作物品质。","description":"植物提取物螯合的新一代钙肥，Ca≥10%（实测Ca≥20%），含硼锌。未添加氮素，不会引起果实返青和延迟上色，可与磷酸二氢钾混合使用","advantages":"植物提取物螯合技术，钙移动快；不含氮，不返青；可与磷酸二氢钾混用：\n\n1.采用植物提取物进行螯合的新一代钙肥，攻克了钙元素在植物体内移动极其缓慢的生理传导难题。\n2.选用高纯度原料，不含任何激素成分，安全性高，在推荐使用倍数下具备良好的混配性，可与磷酸二氢钾同施。","ingredients":"Ca≥10.0%（实测Ca≥20.0%）、B≥0.15%、Zn≥0.05%","functions":"补钙、防裂果、防脐腐病、增强果实硬度、可与磷酸二氢钾混用：\n\n1.补钙效率高，吸收更稳定：本肥采用特殊螯合工艺，可应用于对钙需求量大或易缺钙的作物和关键生育期，不会引起果实返青和营养过剩问题。\n2.促进作物生长与果实发育：本品氨基酸含量高，养分全面，安全性高，可与多种营养元素配合使用，提高肥料利用率。\n3.促进营养吸收与代谢：沣惠中的中量元素和营养成分，有利于农作物根系发育、增强光合作用，促进作物生长，提高果实品质。\n4.预防缺钙引起的生理问题：针对因缺钙导致的裂果、苦痘病、脐腐病、叶焦病以及植株萎蔫等问题，具有较好的预防和改善作用。\n5.提升果实硬度和耐储运性：钙元素能促进细胞壁形成，增强果实硬度和韧性，减少采后运输过程中的损伤。","applicable_crops":"果树、蔬菜、瓜类等需钙作物","usage":"冲施/滴灌1-2公斤/亩；叶面喷雾1000-1500倍，10-20g一壶水。粉剂叶面肥","price_range":"1Kg/袋","mix_profile":{"ph":"7","has_copper":false,"copper_level":"none","has_calcium":true,"has_humic_acid":false,"has_amino_acid":false,"has_microbe":false,"has_phosphorus":false,"has_silicon":false,"is_alkaline":false,"is_acidic":false},"manufacturer":"皓泽农业（广州）有限公司","seller":"深圳惠民皓天生态科技有限公司","origin":"中国","registrations":{"execution_standard":"NY2266-2012","record_number":"ZLSRGD2022-00336"},"specifications":[{"name":"1Kg","capacity":"1Kg","form":"粉剂"}],"images":["images/products/fenghui1.png"]}', '2026-08-22T01:14:46.869Z');
INSERT OR REPLACE INTO legacy_product_specs (id, product_id, name, capacity, form, payload_json, sort_order) VALUES ('legacy-spec-a0b117e1397da4504644783e3e03', 'fenghui', '1Kg', '1Kg', '粉剂', '{"name":"1Kg","capacity":"1Kg","form":"粉剂"}', '0');
INSERT OR REPLACE INTO legacy_pesticides (component, payload_json, updated_at) VALUES ('氯溴异氰尿酸', '{"component":"氯溴异氰尿酸","aliases":["消菌灵","菌毒清"],"category":"杀菌剂","chemical_class":"卤代异氰尿酸类消毒剂、广谱杀菌剂","problems":"高效防治各类细菌性、真菌性、病毒性病害，适用于作物溃疡病、角斑病、软腐病、霜霉病、疫病、炭疽病、病毒病等，同时可用于土壤、种苗消毒杀菌","usage":"参考：600-1500倍叶面喷雾，土壤消毒可稀释300-500倍喷淋或灌根（具体以产品标签为准）","precautions":"不可与碱性农药、有机磷农药混用；高温时段慎用，避免药液快速蒸发引发药害；喷施后短时间内遇雨需补喷；对部分敏感作物幼苗期减量使用","brands":[{"name":"消菌灵","company":"江苏泰禾"},{"name":"绿亨溴氯","company":"绿亨科技"}],"related":[],"flags":{"is_copper":false,"is_fungicide":true,"is_basic":false,"suggest_alone":true}}', '2026-08-22T01:14:46.869Z');
